from app.unit_of_work import UnitOfWork


def new_thing(n: int = 1, **values: Any) -> Thing:
    """A valid Thing that is not stored yet; `n` makes its unique values differ, `values` replace any of them."""
    defaults: dict[str, Any] = {"id": bytes([n % 256]) * 16, "tiny": n, "small": n, "medium": n, "num": n, "big": n, "price": Decimal(f"{n % 10000}.50"), "r": n + 0.5, "d": n + 0.5, "flag": True, "born": date(2026, 1, n % 28 + 1), "opens": time(12, n % 60), "at": datetime(2026, 1, n % 28 + 1, 12, 0, 0), "changed": datetime(2026, 1, n % 28 + 1, 12, 0, 0), "bin": bytes([n % 256]) * 50, "blobby": bytes([n % 256]), "data": {"n": n}, "feeling": "sad", "code": f"{n:05d}"[-5:], "note": f"note-{n}", "long_note": f"longnote-{n}"}
    return Thing(**(defaults | values))


def add_thing(uow: UnitOfWork, n: int = 1) -> Thing:
    """A stored Thing."""
    return uow.things.insert(new_thing(n))


